// InvoiceDesk: turn each IMAP message into the POST /api/v1/ingest/email payload and sign it.
// The signature is HMAC-SHA256 over the exact body string the next node sends (raw body).
// Needs NODE_FUNCTION_ALLOW_BUILTIN=crypto and INGEST_WEBHOOK_SECRET in the n8n environment.
const crypto = require('crypto');

const ALLOWED_TYPES = new Set(['application/pdf', 'image/jpeg', 'image/png', 'image/heic', 'image/heif']);
const MAX_BYTES = 10 * 1024 * 1024; // API limit per file
const MAX_ATTACHMENTS = 10;         // API limit per e-mail
const secret = $env.INGEST_WEBHOOK_SECRET;
if (!secret) {
  throw new Error('INGEST_WEBHOOK_SECRET is not set in the n8n environment');
}

function addressOf(from) {
  if (!from) return '';
  if (typeof from === 'string') {
    const m = from.match(/<([^<>\s]+@[^<>\s]+)>/);
    return (m ? m[1] : from).trim();
  }
  if (Array.isArray(from.value) && from.value.length > 0 && from.value[0].address) {
    return String(from.value[0].address).trim();
  }
  if (typeof from.text === 'string') return addressOf(from.text);
  return '';
}

function bodyText(mail) {
  if (typeof mail.text === 'string' && mail.text.trim() !== '') return mail.text;
  if (typeof mail.html === 'string') {
    return mail.html.replace(/<(script|style)[\s\S]*?<\/\1>/gi, ' ').replace(/<[^>]+>/g, ' ')
      .replace(/&nbsp;/g, ' ').replace(/[ \t]+/g, ' ').trim();
  }
  return '';
}

const out = [];
const items = $input.all();
for (let i = 0; i < items.length; i++) {
  const mail = items[i].json || {};
  const binary = items[i].binary || {};
  const attachments = [];
  const skipped = [];
  for (const key of Object.keys(binary).sort()) {
    const meta = binary[key] || {};
    const type = String(meta.mimeType || '').toLowerCase().split(';')[0].trim();
    const filename = String(meta.fileName || key).slice(0, 255);
    if (!ALLOWED_TYPES.has(type)) { skipped.push({ filename, reason: 'type ' + (type || 'unknown') }); continue; }
    if (attachments.length >= MAX_ATTACHMENTS) { skipped.push({ filename, reason: 'too many attachments' }); continue; }
    const data = await this.helpers.getBinaryDataBuffer(i, key);
    if (data.length > MAX_BYTES) { skipped.push({ filename, reason: 'over 10 MB' }); continue; }
    attachments.push({ filename, content_type: type, content_b64: data.toString('base64') });
  }

  const from = addressOf(mail.from).slice(0, 320) || 'unknown@invalid';
  const subject = String(mail.subject || '').slice(0, 998);
  const text = bodyText(mail).slice(0, 200000);
  const date = mail.date ? new Date(mail.date) : null;
  let messageId = String(mail.messageId || '').trim();
  if (!messageId) {
    // Stable fallback so an n8n retry of the same message maps to the same record.
    const h = crypto.createHash('sha256').update([from, subject, String(mail.date || ''), text].join('\n')).digest('hex');
    messageId = '<n8n-' + h.slice(0, 32) + '@invoicedesk.local>';
  }

  const payload = {
    message_id: messageId.slice(0, 998),
    from,
    subject,
    body_text: text,
    received_at: date && !isNaN(date.getTime()) ? date.toISOString() : null,
    attachments,
  };
  const body = JSON.stringify(payload);
  const signature = 'sha256=' + crypto.createHmac('sha256', secret).update(body, 'utf8').digest('hex');
  out.push({ json: { body, signature, message_id: payload.message_id, attachments: attachments.length, skipped } });
}
return out;
